def spiral_fill(indices, grid_size=5):
    output = [[None] * grid_size for _ in range(grid_size)]
    idx = 0
    top, bottom = 0, grid_size - 1
    left, right = 0, grid_size - 1

    while idx < len(indices) and (top <= bottom and left <= right):
        for c in range(left, right + 1):
            if idx < len(indices):
                output[top][c] = indices[idx]
                idx += 1
        top += 1

        for r in range(top, bottom + 1):
            if idx < len(indices):
                output[r][right] = indices[idx]
                idx += 1
        right -= 1

        if top <= bottom:
            for c in range(right, left - 1, -1):
                if idx < len(indices):
                    output[bottom][c] = indices[idx]
                    idx += 1
            bottom -= 1

        if left <= right:
            for r in range(bottom, top - 1, -1):
                if idx < len(indices):
                    output[r][left] = indices[idx]
                    idx += 1
            left += 1
    return output

